package com.fadlurahmanfdev.crypto_vault.domain.models

/**
 * Result of an AES encryption.
 *
 * @property text Ciphertext. For GCM it includes the authentication tag.
 * @property iv Initialization vector generated by the cipher. Required for decryption; not secret.
 */
data class EncryptedData(
    val text: ByteArray,
    val iv : ByteArray
) {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (javaClass != other?.javaClass) return false

        other as EncryptedData

        if (!text.contentEquals(other.text)) return false
        if (!iv.contentEquals(other.iv)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = text.contentHashCode()
        result = 31 * result + iv.contentHashCode()
        return result
    }
}
